# frozen_string_literal: true

require "test_helper"
require "vblank/original/symbol_file"

# Each assembler writes where it put every label in a format of its own. Original::SymbolFile reads
# each into Original::Labels. The files here are made up, a few lines in each format.
class TestSymbolFile < Minitest::Test
  SymbolFile = VBlank::Original::SymbolFile

  # rgblink's .sym: `bank:address name`, the address as the Game Boy's processor sees it.
  RGBLINK = <<~SYM
    ; File generated by rgblink
    00:0150 Start
    00:0158 Start.loop
    01:4000 Music_Title
    01:4010 Music_Credits
    03:4000 Pictures
    00:c000 wScore
    00:c002 wBalls
    00:c002 wBalls.first
    00:ff80 hFrame
  SYM

  def test_rgblink_banks_become_offsets_in_the_copy
    labels = SymbolFile.rgblink(RGBLINK)

    assert_equal 0x0150, labels.offset("Start")
    assert_equal 0x4010, labels.offset("Music_Credits")
    assert_equal 0xC000, labels.offset("Pictures")
    assert_equal 0x4000, labels.address("Pictures")
    assert_equal 0x3FF0, labels.span("Music_Credits")
  end

  def test_rgblink_ram_labels_keep_their_fields_and_local_labels_are_left_out_unless_asked_for
    labels = SymbolFile.rgblink(RGBLINK)

    assert_equal :ram, labels.fetch("wScore").space
    assert_equal 0xC002, labels.address("wBalls.first")
    assert_equal 0xFF80, labels.address("hFrame")
    assert_raises(VBlank::Original::UnknownLabel) { labels.offset("Start.loop") }
    assert_equal 0x0158, SymbolFile.rgblink(RGBLINK, local_labels: true).offset("Start.loop")
  end

  # sfcasm's .sym: the 24-bit address and the name. Work RAM is banks $7E and $7F, and the low 8 KB of
  # it shows in the first banks too; the cartridge's place depends on how it is mapped.
  SFCASM = <<~SYM
    c00000 reset
    c4018e main
    c401bd main.loc_C401BD
    7e0010 player_1
    7e0012 player_1.x_position
    000100 frame_count
    002100 INIDISP
  SYM

  def test_sfcasm_hirom_and_lorom_place_labels_in_the_copy
    hirom = SymbolFile.sfcasm(SFCASM, mapping: :hirom)
    lorom = SymbolFile.sfcasm("808000 reset\n81a000 table\n", mapping: :lorom)

    assert_equal 0x4018E, hirom.offset("main")
    assert_equal 0xC4018E, hirom.address("main")
    assert_equal 0x8000 + 0x2000, lorom.offset("table")
    assert_equal 0, lorom.offset("reset")
  end

  def test_sfcasm_ram_labels_and_struct_fields_are_kept_and_registers_left_out
    labels = SymbolFile.sfcasm(SFCASM, mapping: :hirom)

    assert_equal 0x7E0012, labels.address("player_1.x_position")
    assert_equal :ram, labels.fetch("frame_count").space
    assert_raises(VBlank::Original::UnknownLabel) { labels.fetch("INIDISP") }
    assert_raises(VBlank::Original::UnknownLabel) { labels.fetch("main.loc_C401BD") }
  end

  def test_sfcasm_needs_a_mapping_it_knows
    assert_match "hirom", assert_raises(ArgumentError) { SymbolFile.sfcasm(SFCASM, mapping: :exhirom) }.message
  end

  # asm68k's listing: the address in eight hex digits, then `=` and a value for a name given one, and
  # the source line from the 37th column.
  private def listing_line(address, source, value: nil)
    front = format("%08X", address)
    front += format(" =%08X", value) if value
    "#{front.ljust(36)}#{source}\n"
  end

  private def listing
    [listing_line(0, "Vectors:"), listing_line(0x200, "EntryPoint:"), listing_line(0x210, ".loop:"),
     listing_line(0x220, "\tincbin\t\"data/pal.bin\""), listing_line(0, "SPEED\t\tequ\t4", value: 4),
     listing_line(0, "score\t\trs.w\t1", value: 0xFF0000), listing_line(0, "lives\t\trs.b\t1", value: 0xFF0002),
     listing_line(0, "board\t\trs.b\t72", value: 0xFF0003), listing_line(0, "board_end\t\trs.b\t0", value: 0xFF004B),
     listing_line(0, "timer\t\trs.l\tTIMERS", value: 0xFF004B), listing_line(0, "last\t\trs.b\t1", value: 0xFF0050)].join
  end

  def test_asm68k_listing_labels_are_offsets_and_reserved_ram_keeps_width_and_size
    labels = SymbolFile.asm68k_listing(listing)

    assert_equal 0x200, labels.offset("EntryPoint")
    assert_equal [2, 2], labels.fetch("score").then { [it.width, it.size] }
    assert_equal [1, 72], labels.fetch("board").then { [it.width, it.size] }
    assert_equal 0, labels.fetch("board_end").size
    assert_equal [4, 5], labels.fetch("timer").then { [it.width, it.size] }
    assert_equal 0xFF0003, labels.address("board")
    assert_raises(VBlank::Original::UnknownLabel) { labels.fetch("SPEED") }
  end

  def test_asm68k_local_labels_belong_to_the_label_before_them
    assert_equal 0x210, SymbolFile.asm68k_listing(listing, local_labels: true).offset("EntryPoint.loop")
    assert_raises(VBlank::Original::UnknownLabel) { SymbolFile.asm68k_listing(listing).fetch("EntryPoint.loop") }
  end

  # The GNU linker's map (`ld -Map`), which a decompilation built with it writes: a symbol is a line
  # of its address and name alone, under the section it is in.
  GNU_LD_MAP = <<~MAP
    Memory Configuration

    Name             Origin             Length             Attributes
    *default*        0x0000000000000000 0xffffffffffffffff

    Linker script and memory map

                    0x0000000002000000                . = 0x2000000
     .bss           0x0000000002000000       0x10 build/src/main.o
                    0x0000000002000000                gPlayer
                    0x0000000002000008                gEnemies
                    0x0000000003000010                gFrameCount
     .text          0x0000000008000000      0x2a4 asm/crt0.o
                    0x0000000008000000                _start
                    0x00000000080000c0                AgbMain
     .rodata.long_section_name
                    0x0000000008100000       0x40 data/maps.o
                    0x0000000008100000                gAreaMaps
                    0x0000000004000000                REG_DISPCNT
  MAP

  def test_gnu_ld_map_places_cartridge_and_work_ram_symbols
    labels = SymbolFile.gnu_ld_map(GNU_LD_MAP)

    assert_equal 0x100000, labels.offset("gAreaMaps")
    assert_equal 0x8100000, labels.address("gAreaMaps")
    assert_equal 0xC0, labels.offset("AgbMain")
    assert_equal 8, labels.span("gPlayer")
    assert_equal :ram, labels.fetch("gFrameCount").space
    assert_raises(VBlank::Original::UnknownLabel) { labels.fetch("REG_DISPCNT") }
  end
end
